using Essco.Application.Inventory;using Essco.Application.Security;using Essco.Domain.Inventory;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Inventory;[Authorize(Policy=Permissions.Warehouse)]public sealed class DetailModel(InventoryService service):PageModel{public PhysicalInventory Inventory{get;private set;}=null!;public IReadOnlyCollection<InventoryItem>Items{get;private set;}=[];public IReadOnlyCollection<InventoryCount>Counts{get;private set;}=[];[BindProperty(SupportsGet=true)]public string?Group{get;set;}[BindProperty]public CountInput Input{get;set;}=new();[TempData]public string?StatusMessage{get;set;}public async Task<IActionResult>OnGetAsync(int id,CancellationToken t){if(!await Load(id,t))return NotFound();return Page();}public async Task<IActionResult>OnPostCountAsync(int id,CancellationToken t){if(!ModelState.IsValid){if(!await Load(id,t))return NotFound();return Page();}var existing=(await service.ListCountsAsync(id,null,t)).FirstOrDefault(x=>x.Group==Input.Group&&x.Number==Input.Number&&x.ItemCode==Input.ItemCode);if(existing is null)return NotFound();var r=await service.SaveCountAsync(existing with{Quantity=Input.Quantity,Recount=existing.Number>=3||existing.Recount},t);StatusMessage=r.Succeeded?"Conteo actualizado.":string.Join(" ",r.Errors);return RedirectToPage(new{id,Group=Input.Group});}public async Task<IActionResult>OnPostCloseAsync(int id,decimal entries,decimal exits,CancellationToken t){if(!ModelState.IsValid){if(!await Load(id,t))return NotFound();return Page();}StatusMessage=await service.CloseAsync(id,entries,exits,t)?"Inventario cerrado.":"No fue posible cerrar el inventario.";return RedirectToPage(new{id});}private async Task<bool>Load(int id,CancellationToken t){var x=await service.GetAsync(id,t);if(x is null)return false;Inventory=x;Items=await service.ListItemsAsync(id,t);Counts=await service.ListCountsAsync(id,Group,t);return true;}public sealed class CountInput{public string Group{get;set;}="";public int Number{get;set;}public string ItemCode{get;set;}="";public decimal Quantity{get;set;}public bool Recount{get;set;}}}
